<?php $edit=!empty($acuerdo);$action=$edit?'admin/acuerdos/editar/'.$acuerdo->id:'admin/acuerdos/crear'; ?><div class="card"><div class="card-body"><?php if($error): ?><div class="alert alert-danger"><?= html_escape($error) ?></div><?php endif; ?><?= form_open_multipart($action) ?><div class="mb-3"><label>Grupo</label><select class="form-select" name="grupo_id" required><?php foreach($grupos as $g): ?><option value="<?= (int)$g->id ?>" <?= (($edit && (int)$acuerdo->grupo_id===(int)$g->id) || (!$edit && (int)$this->input->get('grupo_id')===(int)$g->id))?'selected':'' ?>><?= html_escape($g->descripcion) ?></option><?php endforeach; ?></select></div><div class="mb-3"><label>Título</label><input class="form-control" name="titulo" maxlength="255" required value="<?= html_escape($edit?$acuerdo->titulo:'') ?>"></div><div class="mb-3"><label>Fecha del acuerdo</label><input type="date" class="form-control" name="fecha_acuerdo" required value="<?= html_escape($edit?$acuerdo->fecha_acuerdo:'') ?>"></div><div class="mb-3"><label>URL alternativa</label><input type="url" class="form-control" name="url" value="<?= html_escape($edit?$acuerdo->url:'') ?>"></div><div class="mb-3"><label>PDF</label><input type="file" class="form-control" name="archivo" accept="application/pdf"></div><label><input type="checkbox" name="activo" value="1" <?= $edit&&$acuerdo->activo?'checked':'' ?>> Publicar acuerdo</label><div class="mt-3"><button class="btn btn-corponor">Guardar</button></div><?= form_close() ?></div></div>